	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeRuleError(w, r, newError(422, "VALIDATION_ERROR", "请求体不是合法 JSON"))
		return
	}
	result, err := s.Preview(r.Context(), identity.AccountIDFrom(r.Context()),
